SELECT DISTINCT m.PERM_URL FROM sys_menu m inner join (SELECT ria.role_id, ia.menu_id FROM sys_industry_auth ia INNER JOIN sys_role_industry_auth ria ON ia.auth_id = ria.auth_id WHERE 1=1
and ia.industry_code = #{user.industryCode}
and ia.app_ver_code = #{user.appVerCode}
#{item}
) tmp on tmp.menu_id = m.MENU_ID WHERE 1=1
and m.MENU_CLASSIFY like '%0%'
and m.MENU_CLASSIFY like '%1%'

SELECT DISTINCT tmp.role_id, m.perm_url FROM sys_menu m inner join (SELECT ria.role_id, ia.menu_id FROM sys_industry_auth ia INNER JOIN sys_role_industry_auth ria ON ia.auth_id = ria.auth_id WHERE 1=1
and ia.industry_code = #{user.industryCode}
and ia.app_ver_code = #{user.appVerCode}
#{item}
) tmp on tmp.menu_id = m.MENU_ID WHERE 1=1
and m.MENU_CLASSIFY like '%0%'
and m.MENU_CLASSIFY like '%1%'

