SELECT d.dept_id AS deptCode, d.DEPT_NAME AS deptName, d.parent_id AS parentdeptCode, d.order_num AS orderNum FROM sys_dept d WHERE d.del_flag = '0' AND d.TENANT_ID = #{tenantId} AND d.industry_code = #{industryCode} AND d.APP_VER_CODE = #{appVerCode} AND EXISTS ( WITH recursive t1 ( dept_id, parent_id ) AS ( SELECT t0.dept_id, t0.parent_id FROM sys_dept t0 WHERE t0.dept_id = #{deptId} UNION ALL SELECT t2.dept_id, t2.parent_id FROM sys_dept t2, t1 WHERE t2.parent_id = t1.dept_id ) SELECT 1 FROM t1 WHERE t1.dept_id = d.DEPT_ID )
${dataScope}
ORDER BY d.parent_id ASC, d.dept_id ASC, d.order_num ASC

SELECT d.dept_id AS deptCode, d.DEPT_NAME AS deptName, d.parent_id AS parentdeptCode, d.order_num AS orderNum, d2.device_code, d2.device_type, d2.industry_code, d2.APP_VER_CODE FROM sys_dept d LEFT JOIN vm_organ_device_rel_t d2 ON d.dept_id = d2.dept_id AND d.TENANT_ID = d2.TENANT_ID AND d.industry_code = d2.industry_code AND d.APP_VER_CODE = d2.APP_VER_CODE WHERE d.del_flag = '0' AND d2.delete_flag = '0' AND d.TENANT_ID = #{tenantId} AND d.industry_code = #{industryCode} AND d.APP_VER_CODE = #{appVerCode} AND EXISTS ( WITH recursive t1 ( dept_id, parent_id ) AS ( SELECT t0.dept_id, t0.parent_id FROM sys_dept t0 WHERE t0.dept_id = #{deptId} UNION ALL SELECT t2.dept_id, t2.parent_id FROM sys_dept t2, t1 WHERE t2.parent_id = t1.dept_id ) SELECT 1 FROM t1 WHERE t1.dept_id = d.DEPT_ID )
${dataScope}
ORDER BY d.parent_id ASC, d.dept_id ASC, d.order_num ASC

SELECT d.dept_id AS deptCode, d.DEPT_NAME AS deptName, d.parent_id AS parentdeptCode, d.order_num AS orderNum, d2.province_code, d2.city_code, d2.county_code, d2.street_code, d2.category_code, d2.industry_code, d2.APP_VER_CODE FROM sys_dept d LEFT JOIN vm_organ_street_rel_t d2 ON d.dept_id = d2.dept_id AND d.TENANT_ID = d2.TENANT_ID AND d.industry_code = d2.industry_code AND d.APP_VER_CODE = d2.APP_VER_CODE WHERE d.del_flag = '0' AND d2.delete_flag = '0' AND d.TENANT_ID = #{tenantId} AND d.industry_code = #{industryCode} AND d.APP_VER_CODE = #{appVerCode} AND EXISTS ( WITH recursive t1 ( dept_id, parent_id ) AS ( SELECT t0.dept_id, t0.parent_id FROM sys_dept t0 WHERE t0.dept_id = #{deptId} UNION ALL SELECT t2.dept_id, t2.parent_id FROM sys_dept t2, t1 WHERE t2.parent_id = t1.dept_id ) SELECT 1 FROM t1 WHERE t1.dept_id = d.DEPT_ID )
${dataScope}
ORDER BY d.parent_id ASC, d.dept_id ASC, d.order_num ASC
